t.script:
(function () {
    var gclid = new URLSearchParams(location.search).get('gclid');
    if (!gclid || !/^[A-Za-z0-9_-]{1,100}$/.test(gclid)) return;
    var apex = location.hostname.replace(/^(www|products)\./, '');
    // Host-only cookie when there is no dot (localhost/IP);
    // Domain=apex otherwise so the products subdomain can read it.
    var domain = apex.includes('.') ? '; domain=' + apex : '';
    var uk = /(^|\.)co\.uk$/i.test(location.hostname);
    var consent = /(?:^|;\s*)rocersa_consent=v1:([01]):([01]):/.exec(document.cookie || '');
    var marketing = !!(consent && consent[2] === '1');
    if (uk && !marketing) {
        try { sessionStorage.setItem('rocersa_pending_gclid', gclid); } catch (e) {}
        return;
    }
    document.cookie = 'gclid=' + gclid +
        '; path=/' + domain +
        '; max-age=7776000; samesite=lax; secure';
})();
